mapper.select:
SELECT * FROM BLOCK_CONTACT WHERE MEMBER_NO = #{memberNo}
ORDER BY BLOCK_ID
DESC

mapper.delete:
DELETE FROM
BLOCK_CONTACT WHERE BLOCK_ID = #{blockId} AND MEMBER_NO =
#{memberNo}

mapper.insert:
INSERT INTO MEMBER_PROFILE (
MEMBER_NO, GENDER,
BIRTH_DATE, HEIGHT
) VALUES (
#{memberNo}, #{gender},
TO_DATE(#{birthDate}, 'YYYY-MM-DD'), #{height}
)

mapper.select:
SELECT CODE_ID
FROM
MASTER_CODES
WHERE CODE_NAME = #{codeName}
AND CATEGORY = #{category}

mapper.insert:
INSERT INTO
MEMBER_PHOTOS (
PHOTO_ID, MEMBER_NO, ORIGIN_NAME, RENAME_NAME,
PHOTO_URL, PHOTO_ORDER
) VALUES (
SEQ_PHOTO_ID.NEXTVAL, #{memberNo},
#{originName}, #{renameName}, #{photoUrl}, #{photoOrder}
)

mapper.select:
SELECT COUNT(*) FROM "MEMBER" WHERE
EMAIL NICKNAME PHONE
= #{value}

mapper.update:
UPDATE "MEMBER"
SET LATITUDE = #{latitude},
LONGITUDE =
#{longitude}
WHERE MEMBER_NO = #{memberNo}

mapper.select:
SELECT m.EMAIL
FROM MEMBER m
JOIN MEMBER_PROFILE mp ON m.MEMBER_NO = mp.MEMBER_NO
WHERE m.NAME = #{name}
AND m.PHONE = #{phone}
AND TO_CHAR(mp.BIRTH_DATE, 'YYYYMMDD') = #{birth}
AND m.DEL_FL = 'N'

SELECT COUNT(*)
FROM MEMBER m
JOIN MEMBER_PROFILE mp ON m.MEMBER_NO = mp.MEMBER_NO
WHERE m.EMAIL = #{email}
AND m.NAME = #{name}
AND m.PHONE = #{phone}
AND TO_CHAR(mp.BIRTH_DATE, 'YYYYMMDD') = #{birth}
AND m.DEL_FL = 'N'

mapper.update:
UPDATE MEMBER
SET PASSWORD = #{encPassword}
WHERE EMAIL = #{email}
AND DEL_FL = 'N'
